import { C as subscribers, l as deliveryAddons, n as addons, s as deliveries, t as db } from "../../../../chunks/db.js";
import { t as sellableWithInjera } from "../../../../chunks/addonCatalogue.js";
import { n as fullDate } from "../../../../chunks/format.js";
import { n as isPastCutoff, t as cutoffDateFor } from "../../../../chunks/delivery.js";
import { t as stripe } from "../../../../chunks/stripe.js";
import { error, fail, redirect } from "@sveltejs/kit";
import { asc, eq } from "drizzle-orm";
//#region src/routes/addons/[token]/+page.server.ts
var MAX_QTY = 20;
async function findDelivery(token) {
	const [row] = await db.select({
		id: deliveries.id,
		status: deliveries.status,
		scheduledDate: deliveries.scheduledDate,
		subscriberEmail: subscribers.email,
		subscriberName: subscribers.fullName
	}).from(deliveries).innerJoin(subscribers, eq(subscribers.id, deliveries.subscriberId)).where(eq(deliveries.addonAccessToken, token));
	return row;
}
var load = async ({ params }) => {
	const delivery = await findDelivery(params.token);
	if (!delivery) error(404, "This link is no longer valid.");
	const [catalogue, existingAddons] = await Promise.all([db.select().from(addons).where(sellableWithInjera()).orderBy(asc(addons.sortOrder)), db.select({
		name: addons.name,
		quantity: deliveryAddons.quantity
	}).from(deliveryAddons).innerJoin(addons, eq(addons.id, deliveryAddons.addonId)).where(eq(deliveryAddons.deliveryId, delivery.id))]);
	return {
		name: delivery.subscriberName ?? "there",
		deliveryLabel: fullDate(delivery.scheduledDate),
		open: delivery.status === "scheduled" && !isPastCutoff(delivery.scheduledDate),
		cutoffLabel: fullDate(cutoffDateFor(delivery.scheduledDate)),
		catalogue,
		existingAddons,
		maxQty: MAX_QTY
	};
};
var actions = { checkout: async ({ request, params, url }) => {
	const delivery = await findDelivery(params.token);
	if (!delivery) error(404, "This link is no longer valid.");
	if (delivery.status !== "scheduled" || isPastCutoff(delivery.scheduledDate)) return fail(400, { error: "This delivery can no longer be changed." });
	const formData = await request.formData();
	const catalogue = await db.select().from(addons).where(sellableWithInjera());
	const items = [];
	for (const addon of catalogue) {
		const raw = formData.get(`qty_${addon.id}`);
		if (raw === null) continue;
		const qty = Number(raw);
		if (!Number.isInteger(qty) || qty < 0 || qty > MAX_QTY) return fail(400, { error: "Invalid quantity." });
		if (qty > 0) items.push({
			id: addon.id,
			name: addon.name,
			pricePence: addon.pricePence,
			quantity: qty
		});
	}
	if (items.length === 0) return fail(400, { error: "Pick at least one extra." });
	let session;
	try {
		session = await stripe.checkout.sessions.create({
			mode: "payment",
			customer_email: delivery.subscriberEmail,
			line_items: items.map((item) => ({
				price_data: {
					currency: "gbp",
					product_data: { name: item.name },
					unit_amount: item.pricePence
				},
				quantity: item.quantity
			})),
			success_url: `${url.origin}/addons/${params.token}?success=1`,
			cancel_url: `${url.origin}/addons/${params.token}?canceled=1`,
			payment_intent_data: { metadata: {
				kind: "delivery-addon",
				deliveryId: delivery.id
			} },
			metadata: {
				kind: "delivery-addon",
				deliveryId: delivery.id,
				items: JSON.stringify(items.map((item) => ({
					id: item.id,
					quantity: item.quantity
				})))
			}
		});
	} catch (e) {
		console.error("addons/[token] checkout failed", e);
		return fail(500, { error: "Could not start payment. Please try again." });
	}
	redirect(303, session.url);
} };
//#endregion
export { actions, load };
